import java.io.BufferedReader
import java.io.InputStreamReader

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val n = reader.readLine().trim()
    val nLength = n.length
    if (nLength == 1) {
        println(n)
        return
    }

    fun arrayMultiply(arr: List<Int>): Long {
        var res = 1L
        for (i in arr) {
            res *= i
        }
        return res
    }

    if (n.substring(1, nLength) == "9".repeat(nLength - 1)) {
        val digits = n.map { it.toString().toInt() }
        println(arrayMultiply(digits))
        return
    }

    val nList = n.map { it.toString().toInt() }.toMutableList()
    var max = arrayMultiply(nList)

    for (i in 0 until nLength - 1) {
        val arr = nList.toMutableList()
        arr[i] = arr[i] - 1
        for (j in i + 1 until nLength) {
            arr[j] = 9
        }
        for (j in nLength - 1 downTo 1) {
            if (arr[j] == 0) {
                arr[j] = 9
                arr[j - 1] = arr[j - 1] - 1
            }
            if (arr[j] == -1) {
                arr[j] = 9
                arr[j - 1] = arr[j - 1] - 1
            }
        }
        if (arr[0] == 0) {
            arr.removeAt(0)
        }
        max = kotlin.math.max(max, arrayMultiply(arr))
    }

    println(max)
}

